/// listeners: [{
/// instancePort: 8000,
/// instanceProtocol: "http",
/// lbPort: 80,
/// lbProtocol: "http",
/// }],
/// });
/// const foo = new aws.elb.AppCookieStickinessPolicy("foo", {
/// name: "foo_policy",
/// loadBalancer: lb.name,
/// lbPort: 80,
/// cookieName: "MyAppCookie",
/// });
/// ```
